Method.Implementation:
	#dim list As IHC.ITF.ITFCOMMON.HDD.LookupResponse
	#dim hddObj As IHC.ITF.ITFCOMMON.HDD.Object
	set hddObj = ""

	set list = pResponse.listOfHDDobj
  	// $$$TRACE("IHC.ITF.ITFCOMMON.HDD.LookupResponse list count: " _ list.Count())
  	set listInd = list.Next("")
	while ( listInd '= "")
	{
		set hddObj = list.GetAt(listInd)
		if (hddObj.Index = index)
		{
			return hddObj
		}
		// $$$TRACE( listInd _ " " _ list.GetAt(listInd).NCID _ " = " _  list.GetAt(listInd).Rep)
		set listInd = list.Next(listInd)
	}
	return ""

	#dim list As IHC.ITF.ITFCOMMON.HDD.LookupResponse
	#dim hddObj As IHC.ITF.ITFCOMMON.HDD.Object
	set hddObj = ""
	set list = inp.listOfHDDobj
  	// $$$TRACE("IHC.ITF.ITFCOMMON.HDD.ConvertCase list count: " _ list.Count())
  	set listInd = list.Next("")
	while ( listInd '= "")
	{
		set hddObj = list.GetAt(listInd)
		set hddObj.Rep = $ZCONVERT(hddObj.Rep, "W")
		// $$$TRACE("IHC.ITF.ITFCOMMON.HDD.ConvertCase New Value: " _ hddObj.Rep )
		set listInd = list.Next(listInd)
	}

	Quit $$$OK
